import XCTest
@testable import CuardachCore

/// Checks the committed sample (Samples/courtyard-hunt.arhunt, generated by
/// Samples/make_sample.py) against the Swift implementation.
final class SampleBundleTests: XCTestCase {
    var sampleFolder: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Samples/courtyard-hunt.arhunt")
    }

    func testSampleOpensAndValidates() throws {
        let b = try ExperienceBundle.open(folder: sampleFolder)
        let issues = BundleValidator(bundle: b).validate(b.experience)
        XCTAssertEqual(issues.filter { $0.severity == .error }, [])
        XCTAssertEqual(b.experience.elements.count, 6)
        // Every trigger the engine knows is demonstrated.
        let triggers = Set(b.experience.elements.flatMap(\.behaviours).map(\.trigger))
        XCTAssertEqual(triggers, [.start, .tap, .proximityEnter, .dwell, .timeWindow])
    }

    func testSampleMarkersMatchSwiftPattern() throws {
        for id in ["heron", "lamp", "fragment"] {
            let png = try Data(contentsOf: sampleFolder.appendingPathComponent("markers/\(id).png"))
            let (w, pixels) = try decodeRGB(png)
            let pattern = MarkerPattern(seed: id)
            let cell = w / (pattern.size + 2)
            for r in 0..<pattern.size {
                for c in 0..<pattern.size {
                    let x = (c + 1) * cell + cell / 2, y = (r + 1) * cell + cell / 2
                    let black = pixels[y * (1 + w * 3) + 1 + x * 3] == 0
                    XCTAssertEqual(black, pattern[r, c], "\(id) cell \(r),\(c)")
                }
            }
        }
    }

    /// Minimal decoder for the 8-bit RGB, filter-0 PNGs the sample script writes.
    private func decodeRGB(_ d: Data) throws -> (width: Int, raw: [UInt8]) {
        let b = [UInt8](d)
        XCTAssertEqual(Array(b[0..<8]), [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])
        var p = 8, width = 0, idat = Data()
        func be32(_ i: Int) -> Int { Int(b[i]) << 24 | Int(b[i + 1]) << 16 | Int(b[i + 2]) << 8 | Int(b[i + 3]) }
        while p < b.count {
            let len = be32(p)
            let tag = String(decoding: b[(p + 4)..<(p + 8)], as: UTF8.self)
            if tag == "IHDR" { width = be32(p + 8) }
            if tag == "IDAT" { idat.append(contentsOf: b[(p + 8)..<(p + 8 + len)]) }
            p += 12 + len
        }
        // zlib: 2-byte header, raw DEFLATE, Adler-32 trailer (ignored).
        let raw = try Inflate.decompressPortable(idat.dropFirst(2))
        return (width, [UInt8](raw))
    }
}
